// Creatures with flying can't attack or block, and their activated abilities with {T} in their costs can't be activated.
#[allow(unused_imports)] use cantrip_api::*;
#[allow(unused_variables)] fn ability_1_affects(q: &dyn LayerQuery, source: ObjectId, affected: ObjectId, so_far: &Chars) -> bool { let asker = &Asker::new(source, q.controller(source)); ((*so_far).is(CardType::Creature) && (*so_far).keywords.has(Keyword::Flying)) }
#[allow(unused_variables)] fn ability_1_0_rule(q: &dyn Query, asker: &Asker, attacker: ObjectId, defender: Target) -> bool { let source = asker.source; let asker = &Asker::new(source, q.controller(source)); !((q.chars(attacker).is(CardType::Creature) && q.chars(attacker).keywords.has(Keyword::Flying))) }
#[allow(unused_variables)] fn ability_1_1_rule(q: &dyn Query, source: ObjectId, blocker: ObjectId, attacker: ObjectId) -> bool { let asker = &Asker::new(source, q.controller(source)); !((q.chars(blocker).is(CardType::Creature) && q.chars(blocker).keywords.has(Keyword::Flying)) && true) }
#[allow(unused_variables)] fn ability_1_2_rule(q: &dyn Query, asker: &Asker, object: ObjectId, ability: &ActivatedDef) -> bool { let id = object; !(q.is_on_battlefield(id) && (q.chars(id).is(CardType::Creature) && q.chars(id).keywords.has(Keyword::Flying)) && (ability.cost.tap)) }

